from ..utils.logger import logger


class StatusPrinter:

    @staticmethod
    def print_start_info(env):
        """Print start message.

        :param Environment env:       Object containing environment configuration
        """
        msg = (
            f"\n\n"
            f"-------------------------------------------------------------------\n"
            f"               Robot Framework - Reporting Portal script\n"
            f"------------------+------------------------------------------------\n"
            f" Script Version   |  {StatusPrinter._get_package_version()}\n"
            f" Test Line        |  {env.testline}\n"
            f" Competence Area  |  {env.competence_area}\n"
            f" Phase            |  {env.phase}\n"
            f"------------------+------------------------------------------------\n"
        )
        logger.status(msg)

    @staticmethod
    def print_backup_start_info(backup_dir: str):
        """Print a message about backup process.

        :param string backup_dir: Path to created backup directory.
        """
        msg = (
            f"\n\n"
            f"-------------------------------------------------------------------\n"
            f"               Robot Framework - Reporting Portal script\n"
            f"-------------------+-----------------------------------------------\n"
            f" Script Version    |  {StatusPrinter._get_package_version()}\n"
            f" Backup directory  |  {backup_dir}\n"
            f"-------------------+-----------------------------------------------\n"
        )
        logger.status(msg)

    @staticmethod
    def print_validate_start_info():
        """Print a message about validation process."""

        msg = (
            f"\n\n"
            f"-------------------------------------------------------------------\n"
            f"               Robot Framework - Reporting Portal script\n"
            f"-------------------+-----------------------------------------------\n"
            f" Script Version    |  {StatusPrinter._get_package_version()}\n"
            f"-------------------+-----------------------------------------------\n"
        )
        logger.status(msg)

    @staticmethod
    def print_send_file_start_info(env):
        """Print start message.

        :param Environment env:       Object containing environment configuration

        """
        msg = (
            f"\n\n"
            f"-------------------------------------------------------------------\n"
            f"               Robot Framework - Reporting Portal script\n"
            f"------------------+------------------------------------------------\n"
            f" Zip file path    |  {env.zipfile_path}\n"
            f"------------------+------------------------------------------------\n"
        )
        logger.status(msg)

    @staticmethod
    def print_suite_summary_info(summary: dict):
        """Print start message.

        :param dict summary: Summary from suite collector
        """
        if summary:
            msg = (
                "\n"
                "-------------------------------------------------------------------\n"
                "                            Summary\n"
                "-------------------------------------------------------------------\n"
            )
            logger.status(msg)

            for log in summary:
                logger.status(
                    f"{summary[log][0]}{summary[log][1]} {log}"
                )

    @staticmethod
    def print_end_info():
        """Print a message after the whole report operation ends."""

        logger.status(
            "\n"
            "-------------------------------------------------------------------\n"
            "          Report was successfully sent to Reporting Portal\n"
            "-------------------------------------------------------------------\n\n"
        )

    @staticmethod
    def print_empty_suite_end_info():
        """Prints a message after the whole report operation ends."""
        logger.status(
            "\n"
            "-------------------------------------------------------------------\n"
            "          Report was not sent due to empty suite\n"
            "-------------------------------------------------------------------\n\n"
        )

    @staticmethod
    def print_backup_end_info():
        """Print a message after the whole backup operation ends."""
        logger.status(
            "\n"
            "-------------------------------------------------------------------\n"
            "          Files were successfully put into zip file\n"
            "-------------------------------------------------------------------\n"
        )

    @staticmethod
    def print_validate_end_info():
        """Print a message after the whole validate operation ends."""
        logger.status(
            "\n"
            "-------------------------------------------------------------------\n"
            "                   Validation process finished\n"
            "-------------------------------------------------------------------\n\n"
        )

    @staticmethod
    def print_validation_result(response):
        """Print end message.

        :param Response response:  Response for validation
        """
        if response:
            logger.status(
                "\n"
                "-------------------------------------------------------------------\n"
                "                        Validation results \n"
                "-------------------------------------------------------------------\n"
            )
            for testcase in response:
                test_name = testcase["test_instance_name"][:150]
                result = testcase["Result"]
                phase = testcase["phase"]
                logger.status(
                    f"{test_name} [{result}][{phase}]"
                )
            logger.status(
                "\n"
                "-------------------------------------------------------------------\n"
            )

    @staticmethod
    def print_validate_empty_configs_info():
        """Prints info about attempt to validate empty configs"""
        logger.status(
            "\n"
            "-------------------------------------------------------------------\n\n\n"
            "          No configs matched locally for given testcases\n\n\n"
            "-------------------------------------------------------------------\n\n"
        )

    @staticmethod
    def _get_package_version() -> str:
        from taf.sw.reporting_portal import __version__
        return __version__
